UPDATE countries SET attrs = $j${"Description":"Republic of the Philippines","PhoneCode":"+63"}$j$::jsonb || attrs WHERE code = $s$PH$s$ AND NOT attrs ? $s$Description$s$;
UPDATE countries SET attrs = $j${"Description":"Republic of Singapore","PhoneCode":"+65"}$j$::jsonb || attrs WHERE code = $s$SG$s$ AND NOT attrs ? $s$Description$s$;
UPDATE countries SET attrs = $j${"Description":"Malaysia","PhoneCode":"+60"}$j$::jsonb || attrs WHERE code = $s$MY$s$ AND NOT attrs ? $s$Description$s$;
UPDATE countries SET attrs = $j${"Description":"Kingdom of Thailand","PhoneCode":"+66"}$j$::jsonb || attrs WHERE code = $s$TH$s$ AND NOT attrs ? $s$Description$s$;
UPDATE countries SET attrs = $j${"Description":"United States of America","PhoneCode":"+1"}$j$::jsonb || attrs WHERE code = $s$US$s$ AND NOT attrs ? $s$Description$s$;
UPDATE states SET attrs = jsonb_build_object('Description', name || ' province / region') || attrs WHERE NOT attrs ? 'Description';
UPDATE cities SET attrs = jsonb_build_object('CityCode', upper(left(regexp_replace(name, '[^A-Za-z]', '', 'g'), 3)) || '-' || id, 'Description', name || ' city') || attrs WHERE NOT attrs ? 'CityCode';
UPDATE currencies SET attrs = $j${"ISOcode":"PHP","SmallestUnit":"0.01","UnitDescription":"Centavo","CurrencyFormat":"PHP #,##0.00","Description":""}$j$::jsonb || attrs WHERE code = $s$PHP$s$ AND NOT attrs ? $s$ISOcode$s$;
UPDATE currencies SET attrs = $j${"ISOcode":"USD","SmallestUnit":"0.01","UnitDescription":"Cent","CurrencyFormat":"USD #,##0.00","Description":""}$j$::jsonb || attrs WHERE code = $s$USD$s$ AND NOT attrs ? $s$ISOcode$s$;
UPDATE currencies SET attrs = $j${"ISOcode":"EUR","SmallestUnit":"0.01","UnitDescription":"Cent","CurrencyFormat":"EUR #,##0.00","Description":""}$j$::jsonb || attrs WHERE code = $s$EUR$s$ AND NOT attrs ? $s$ISOcode$s$;
UPDATE currencies SET attrs = $j${"ISOcode":"SGD","SmallestUnit":"0.01","UnitDescription":"Cent","CurrencyFormat":"SGD #,##0.00","Description":""}$j$::jsonb || attrs WHERE code = $s$SGD$s$ AND NOT attrs ? $s$ISOcode$s$;
UPDATE currencies SET attrs = $j${"ISOcode":"JPY","SmallestUnit":"0.01","UnitDescription":"Sen","CurrencyFormat":"JPY #,##0","Description":""}$j$::jsonb || attrs WHERE code = $s$JPY$s$ AND NOT attrs ? $s$ISOcode$s$;
UPDATE policy_types SET attrs = jsonb_build_object('policyTypeDescription', name || ' policy') || attrs WHERE NOT attrs ? 'policyTypeDescription';
UPDATE products SET description = COALESCE(description, name) WHERE description IS NULL;

-- Masters retired by migration 0241_retire_duplicate_masters.sql (each value has one place: the Authority Matrix,
-- Master > Configuration, the Commission Rate Matrix, User Management > User, Petty Cash > Initiate). Records are kept
-- for reference, inactive; the API refuses changes (masters RETIRED_TYPES).
UPDATE master_types SET status = 'inactive', screen = NULL
WHERE status = 'active' AND code IN ('remittance-approval-workflow', 'remittance-reconciliation-rule', 'remittance-electronic-transfer', 'remittance-history-config',
  'remittance-analytics-config', 'remittance-direct-bill', 'remittance-report-template', 'commission', 'employee', 'petty-cash');
